contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address callee, bytes memory data, bool shouldRevert, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");
        require(callee != address(0), "zero callee");

        // Decide which entry point on callee will be called based on shouldRevert.
        // Use a well-formed selector so that the call cannot fail due to calldata shape alone.
        bytes4 sel = shouldRevert ? bytes4(keccak256("revertCall()")) : bytes4(keccak256("okCall()"));
        bytes memory payload = abi.encodeWithSelector(sel);

        uint256 beforeC = address(c).balance;
        address calleeBefore = callee;
        uint256 calleeBalBefore = calleeBefore.balance;

        bool reverted;
        try c.forward{value: amount}(callee, payload) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 calleeBalAfter = calleeBefore.balance;

        // General rule: forward succeeds iff the target call succeeds, and c never retains forwarded Ether.
        assert(reverted == shouldRevert && afterC == beforeC && calleeBalAfter == calleeBalBefore + (shouldRevert ? 0 : amount));
    }
}

